#!/usr/bin/env python3
"""Surgical install of proposal ballot kinds onto /opt/liquidgov.
Does not replace whole files. Aborts if an anchor is missing or duplicated.
Does not touch liquidgov_accounts.lgp or blobs.
"""
import base64, pickle, shutil, sys
from pathlib import Path
from datetime import datetime, timezone

ROOT = Path("/opt/liquidgov")
PAYLOAD = pickle.loads(base64.b64decode(""""""))

def main():
    if not ROOT.exists():
        print("NO /opt/liquidgov"); return 1
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    # already installed?
    hpp = ROOT / "libs/liquidgov_file_store/include/liquidgov/platform/file_store.hpp"
    if not hpp.exists():
        # droplet layout is flattened: /opt/liquidgov/src and maybe headers elsewhere
        print("looking for layout")
    # detect layout
    candidates = {
        "libs/liquidgov_file_store/include/liquidgov/platform/file_store.hpp": [
            ROOT / "libs/liquidgov_file_store/include/liquidgov/platform/file_store.hpp",
            ROOT / "include/liquidgov/platform/file_store.hpp",
        ],
        "libs/liquidgov_file_store/src/file_store.cpp": [
            ROOT / "libs/liquidgov_file_store/src/file_store.cpp",
            ROOT / "src/file_store.cpp",
        ],
        "src/http_server.cpp": [ROOT / "src/http_server.cpp"],
        "tests/file_store_test.cpp": [
            ROOT / "tests/file_store_test.cpp",
            ROOT / "liquidgov-platform/tests/file_store_test.cpp",
        ],
    }
    files = {}
    for rel, opts in candidates.items():
        hit = next((p for p in opts if p.exists()), None)
        files[rel] = hit
        print("path", rel, "->", hit)
    http = files["src/http_server.cpp"]
    if http and "BallotKind::Number" in http.read_text():
        print("ALREADY installed (BallotKind::Number in http_server.cpp)")
        return 0
    applied = 0
    skipped = 0
    for rel, old, new in PAYLOAD:
        p = files.get(rel)
        if p is None:
            print("SKIP missing", rel)
            skipped += 1
            continue
        s = p.read_text()
        n = s.count(old)
        print("patch", rel, "count", n, "old", len(old), "new", len(new))
        if n == 0:
            if rel.endswith("file_store_test.cpp") or "#include <cmath>" in new and "#include <cmath>" in s:
                print("SKIP already/missing", rel)
                skipped += 1
                continue
            print("STOP no match", rel)
            return 2
        if n != 1:
            print("STOP not unique", rel, n)
            return 2
        bak = p.with_suffix(p.suffix + ".bak-ballots-" + stamp)
        if not bak.exists():
            shutil.copy2(p, bak)
        p.write_text(s.replace(old, new, 1))
        applied += 1
    print("applied", applied, "skipped", skipped)
    print("NEXT: cmake --build /opt/liquidgov/build -j1 && chown liquidgov:liquidgov /opt/liquidgov/build/liquidgov_http && systemctl restart liquidgov")
    return 0

if __name__ == "__main__":
    sys.exit(main())
